selector_to_html = {"a[href=\"../element/Hole.html#pyskyfire.injector.element.Hole\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Hole\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.element.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Hole</span></span></dt><dd><p>One hole of an element, placed in the element\u2019s own frame.</p><p>The frame has its origin at the element centre on the face, +x along the\nchamber axis into the chamber, and +y along the element\u2019s orientation.\n<code class=\"docutils literal notranslate\"><span class=\"pre\">exit</span></code> is where the hole meets the face [m], <code class=\"docutils literal notranslate\"><span class=\"pre\">direction</span></code> a unit\nvector along the discharge, and <code class=\"docutils literal notranslate\"><span class=\"pre\">target</span></code> where the jet is drawn to and\nchecked against the wall: the impingement point for an impinging element.</p></dd>", "a[href=\"ImpingingDiagnostics.html#pyskyfire.injector.impinging.ImpingingDiagnostics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingDiagnostics\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.impinging.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpingingDiagnostics</span></span></dt><dd><p>Mixing quantities of one impinging element.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">momentum</span></code> is the magnitude of the summed jet momentum [N] and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">resultant_angle</span></code> its angle from the chamber axis [rad].\n<code class=\"docutils literal notranslate\"><span class=\"pre\">mixture_ratio</span></code> is the element\u2019s oxidizer over fuel mass flow, NaN\nwithout fuel or without any oxidizer feed named. <code class=\"docutils literal notranslate\"><span class=\"pre\">rupe</span></code> and\n<code class=\"docutils literal notranslate\"><span class=\"pre\">momentum_flux_ratio</span></code> are oxidizer over fuel, and NaN unless the element\nhas exactly one fuel and one oxidizer jet.</p></dd>", "a[href=\"Jet.html#pyskyfire.injector.impinging.Jet\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.Jet\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.impinging.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Jet</span></span></dt><dd><p>One jet of an impinging element.</p></dd>", "a[href=\"#pyskyfire-injector-impinging-impingingelement\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">pyskyfire.injector.impinging.ImpingingElement<a class=\"headerlink\" href=\"#pyskyfire-injector-impinging-impingingelement\" title=\"Link to this heading\">\u00b6</a></h1>", "a[href=\"#pyskyfire.injector.impinging.ImpingingElement.diagnostics\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingElement.diagnostics\">\n<span class=\"sig-name descname\"><span class=\"pre\">diagnostics</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">flows</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">oxidizer</span></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference internal\" href=\"ImpingingDiagnostics.html#pyskyfire.injector.impinging.ImpingingDiagnostics\" title=\"pyskyfire.injector.impinging.ImpingingDiagnostics\"><span class=\"pre\">ImpingingDiagnostics</span></a></span></span></dt><dd><p>Mixing quantities of one element.</p><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flows</span></code> is aligned with <a class=\"reference internal\" href=\"#pyskyfire.injector.impinging.ImpingingElement.holes\" title=\"pyskyfire.injector.impinging.ImpingingElement.holes\"><code class=\"xref py py-meth docutils literal notranslate\"><span class=\"pre\">holes()</span></code></a>. <code class=\"docutils literal notranslate\"><span class=\"pre\">oxidizer</span></code> is the set of\nfeeds carrying oxidizer; every other feed carries fuel.</p></dd>", "a[href=\"#pyskyfire.injector.impinging.ImpingingElement.free_jet_length\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingElement.free_jet_length\">\n<span class=\"sig-name descname\"><span class=\"pre\">free_jet_length</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">jet</span></span><span class=\"p\"><span class=\"pre\">:</span></span><span class=\"w\"> </span><span class=\"n\"><a class=\"reference internal\" href=\"Jet.html#pyskyfire.injector.impinging.Jet\" title=\"pyskyfire.injector.impinging.Jet\"><span class=\"pre\">Jet</span></a></span></em><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/functions.html#float\" title=\"(in Python v3.15)\"><span class=\"pre\">float</span></a></span></span></dt><dd><p>Distance a jet travels from its hole to the impingement point [m].</p></dd>", "a[href=\"#pyskyfire.injector.impinging.ImpingingElement.__repr__\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingElement.__repr__\">\n<span class=\"sig-name descname\"><span class=\"pre\">__repr__</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span></dt><dd></dd>", "a[href=\"../element/Element.html#pyskyfire.injector.element.Element\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.element.Element\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.element.</span></span><span class=\"sig-name descname\"><span class=\"pre\">Element</span></span></dt><dd><p>Bases: <a class=\"reference external\" href=\"https://docs.python.org/3/library/abc.html#abc.ABC\" title=\"(in Python v3.15)\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">abc.ABC</span></code></a></p><p>Base class for injector element types.</p></dd>", "a[href=\"#pyskyfire.injector.impinging.ImpingingElement\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingElement\">\n<span class=\"property\"><span class=\"k\"><span class=\"pre\">class</span></span><span class=\"w\"> </span></span><span class=\"sig-prename descclassname\"><span class=\"pre\">pyskyfire.injector.impinging.</span></span><span class=\"sig-name descname\"><span class=\"pre\">ImpingingElement</span></span><span class=\"sig-paren\">(</span><em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">jets</span></span></em>, <em class=\"sig-param\"><span class=\"n\"><span class=\"pre\">impingement_height</span></span></em><span class=\"sig-paren\">)</span></dt><dd><p>Bases: <a class=\"reference internal\" href=\"../element/Element.html#pyskyfire.injector.element.Element\" title=\"pyskyfire.injector.element.Element\"><code class=\"xref py py-obj docutils literal notranslate\"><span class=\"pre\">pyskyfire.injector.element.Element</span></code></a></p><p>Jets drilled to meet at a point <code class=\"docutils literal notranslate\"><span class=\"pre\">impingement_height</span></code> above the face.</p></dd>", "a[href=\"#pyskyfire.injector.impinging.ImpingingElement.holes\"]": "<dt class=\"sig sig-object py\" id=\"pyskyfire.injector.impinging.ImpingingElement.holes\">\n<span class=\"sig-name descname\"><span class=\"pre\">holes</span></span><span class=\"sig-paren\">(</span><span class=\"sig-paren\">)</span> <span class=\"sig-return\"><span class=\"sig-return-icon\">\u2192</span> <span class=\"sig-return-typehint\"><a class=\"reference external\" href=\"https://docs.python.org/3/builtins/stdtypes.html#tuple\" title=\"(in Python v3.15)\"><span class=\"pre\">tuple</span></a><span class=\"p\"><span class=\"pre\">[</span></span><a class=\"reference internal\" href=\"../element/Hole.html#pyskyfire.injector.element.Hole\" title=\"pyskyfire.injector.element.Hole\"><span class=\"pre\">Hole</span></a><span class=\"p\"><span class=\"pre\">,</span></span><span class=\"w\"> </span><span class=\"p\"><span class=\"pre\">...</span></span><span class=\"p\"><span class=\"pre\">]</span></span></span></span></dt><dd><p>Every hole of one element, in the element frame.</p></dd>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 600, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
